# 1. itertools.product 替代嵌套循环
# 不推荐
for color in ["红", "蓝"]:
    for size in ["S", "M", "L"]:
        for material in ["棉", "麻"]:
            print(color, size, material)

# 推荐
from itertools import product
for color, size, material in product(["红", "蓝"], ["S", "M", "L"], ["棉", "麻"]):
    print(color, size, material)

# 2. functools.partial 偏函数
from functools import partial

def power(base, exp):
    return base ** exp

square = partial(power, exp=2)
cube = partial(power, exp=3)

print(square(5))  # 25
print(cube(5))    # 125

# 3. singledispatch 泛型函数
from functools import singledispatch

@singledispatch
def process(arg):
    raise NotImplementedError(f"unsupported type: {type(arg)}")

@process.register(int)
def _(arg):
    return arg * 2

@process.register(str)
def _(arg):
    return arg.upper()

@process.register(list)
def _(arg):
    return [process(x) for x in arg]

